#include "backends/nss/pst_nss_close_state.h"
#include <stdio.h>
#define CHECK(v,n) if(!(v)){printf("test_nss_layered_close: FAIL %d\n",n);return n;}
static int synthetic_failure(pst_u32 original,pst_u32 retained,pst_i32 error,pst_u32 valid,int n){pst_nss_close_state s;pst_nss_close_state_initialize(&s);pst_nss_close_state_set_layer(&s,original);CHECK(pst_nss_close_state_begin(&s),n);pst_nss_close_state_unresolved(&s,retained,error,valid);CHECK(!pst_nss_close_state_begin(&s),n+1);CHECK(s.close_attempted==1UL,n+2);CHECK(s.close_snapshot==PST_NSS_CLOSE_SNAPSHOT_UNRESOLVED_RETAINED,n+3);CHECK(s.descriptor_layer==retained,n+4);CHECK(s.native_error==error,n+5);CHECK(s.native_error_valid==valid,n+6);return 0;}
int main(void){pst_nss_close_state s;int r;r=synthetic_failure(PST_NSS_DESCRIPTOR_LAYER_SSL_AGGREGATE,PST_NSS_DESCRIPTOR_LAYER_SSL_AGGREGATE,-1,1UL,1);CHECK(r==0,10);r=synthetic_failure(PST_NSS_DESCRIPTOR_LAYER_SSL_AGGREGATE,PST_NSS_DESCRIPTOR_LAYER_UNKNOWN_AFTER_CLOSE_FAILURE,-2,1UL,20);CHECK(r==0,30);r=synthetic_failure(PST_NSS_DESCRIPTOR_LAYER_SSL_AGGREGATE,PST_NSS_DESCRIPTOR_LAYER_UNKNOWN_AFTER_CLOSE_FAILURE,-5998,1UL,40);CHECK(r==0,50);r=synthetic_failure(PST_NSS_DESCRIPTOR_LAYER_SSL_AGGREGATE,PST_NSS_DESCRIPTOR_LAYER_UNKNOWN_AFTER_CLOSE_FAILURE,0,0UL,60);CHECK(r==0,70);pst_nss_close_state_initialize(&s);CHECK(pst_nss_close_state_begin(&s),80);pst_nss_close_state_no_resource(&s);CHECK(s.close_snapshot==PST_NSS_CLOSE_SNAPSHOT_NO_NATIVE_RESOURCE&&s.descriptor_layer==PST_NSS_DESCRIPTOR_LAYER_NO_NATIVE_RESOURCE,81);CHECK(!pst_nss_close_state_begin(&s),82);pst_nss_close_state_initialize(&s);pst_nss_close_state_set_layer(&s,PST_NSS_DESCRIPTOR_LAYER_SSL_AGGREGATE);CHECK(pst_nss_close_state_begin(&s),90);pst_nss_close_state_confirmed(&s);CHECK(s.close_snapshot==PST_NSS_CLOSE_SNAPSHOT_CLOSED_CONFIRMED&&s.descriptor_layer==PST_NSS_DESCRIPTOR_LAYER_NO_NATIVE_RESOURCE,91);CHECK(!pst_nss_close_state_begin(&s),92);printf("SYNTHETIC_PRE_CLOSE_FAULT=PASS SYNTHETIC_POST_SSL_POP_FAULT=PASS SYNTHETIC_LOWER_CLOSE_FAILURE=PASS SYNTHETIC_AMBIGUOUS_FAILURE=PASS NORMAL_PR_SUCCESS=PASS NO_SECOND_PR_CLOSE=PASS\n");printf("test_nss_layered_close: PASS\n");return 0;}
